package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Waives the claim's late charge: it bears none from then on. */
public class WaiveClaim {
    public void waive(@Val Claim claim, ClaimRepository repository, Out<Claim> updated) {
        repository.waive(claim);
        updated.set(repository.find(claim.sheetId(), claim.id()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Refuses (400) a waiver unless a steward waives an OPEN or PENDING claim whose late charge is not already waived. */
public class CheckClaimWaive {
    public void check(@RequestParam("user") String user, @Val Claim claim, SettingRepository settings)
            throws InvalidClaimException {
        if (settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidClaimException("Only a steward can waive a claim's late charge.");
        }
        if (!claim.status().open()) {
            throw new InvalidClaimException("A " + claim.status() + " claim's late charge cannot be waived.");
        }
        if (claim.waived()) {
            throw new InvalidClaimException("The claim's late charge is already waived.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim whose late charge was just waived, with its person's name. */
public class AuditClaimWaived {
    public void audit(@Val Claim claim, PersonRepository people, @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_WAIVED sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(claim.number()));
    }
}
-- Whether a steward has waived the claim's late charge: a waived claim bears no late charge from then on.
ALTER TABLE claim ADD COLUMN waived BOOLEAN DEFAULT FALSE NOT NULL;

