  gradesOf: (personId: number) => GradeFrom[],
  rates: Rate[],
  grade: string,
  rate: string,
  rules: DueRules,
): { count: number; diff: string } {
  const candidate: Rate[] = [...rates.filter((r) => r.grade !== grade), { grade, rate, from: null, to: null, sheet: '', version: 1 }];
  const cents = (d: string) => (d === NA ? 0 : hundredths(d));
