package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** A claim as the screen shows it: the amount with two decimals, the date as yyyy-MM-dd, the status by name,
 * the number null unless it has one, the due fixed at settling (two decimals) or null while it is live,
 * the user who opened it or null while it is a draft, whether a statement bound it and the figure it bound
 * it to (two decimals; null: n/a), and the number of the claim a correction corrects (null: not a correction), and its due-by fixed when it was created (yyyy-MM-dd), and its status log, oldest first, and the date it is deferred until (yyyy-MM-dd; null: never deferred), and how many proofs it has been given, and the number of the claim it was split off (null: none), and the user whose open editor locks it (null: not locked), and whether it is a late entry (added while its period was soft-closed), and the last day it was reminded (yyyy-MM-dd; null: never), and its external reference (null: none), and its tags, sorted (none: empty), and the reason it was voided with (null: none), and its comments, oldest first, and the number of the bulk settle batch that settled it (null: none), and its lines, in the order added, and when it was added (on the sequence rates are saved on: see the rate's saved), and whether its late charge was waived, and how many of its proofs are of each kind (receipt, photo), and whether it is held. */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status, String number,
        String due, String openedBy, boolean stated, String statedDue, String corrects, String dueBy,
        List<LogLine> log, String deferredUntil, int proofs, String splitFrom, String lockedBy,
        boolean lateEntry, String reminded, String ref, List<String> tags, String voidReason,
        List<Comment> comments, Integer batch, List<Line> lines, long added, boolean waived, Map<String, Integer> proofKinds, boolean held) {

    /** A line of the status log: the status, the user who gave it, the sheet's today then and the due then. */
    public record LogLine(String status, String by, String date, String due) {
    }

    /** A comment: the user who wrote it, the sheet's today then and its text. */
    public record Comment(String by, String date, String text) {
    }

    /** A line: its label, its quantity and its unit amount (two decimals). */
    public record Line(String label, int qty, String unit) {
    }

    public static ClaimResponse from(Claim claim, List<ClaimLogLine> log) {
        return from(claim, log, null, false, null, null, null, null, List.of(), null, List.of(), 0);
    }

    public static ClaimResponse from(Claim claim, List<ClaimLogLine> log, String lockedBy, boolean lateEntry,
            LocalDate reminded, String ref, String tags, String voidReason, List<ClaimComment> comments,
            Integer batch, List<ClaimLine> lines, int photoProofs) {
        Map<String, Integer> proofKinds = new LinkedHashMap<>();
        proofKinds.put(ProofKind.RECEIPT, claim.proofs() - photoProofs);
        proofKinds.put(ProofKind.PHOTO, photoProofs);
        return new ClaimResponse(claim.id(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.due() == null ? null : claim.due().setScale(2).toPlainString(), claim.openedBy(),
                claim.stated(), claim.statedDue() == null ? null : claim.statedDue().setScale(2).toPlainString(),
                claim.corrects(), claim.dueBy().toString(),
                log.stream().map((l) -> new LogLine(l.status().name(), l.by(), l.date().toString(), l.due())).toList(),
                claim.deferredUntil() == null ? null : claim.deferredUntil().toString(),
                claim.proofs(), claim.splitFrom(), lockedBy, lateEntry,
                reminded == null ? null : reminded.toString(), ref,
                tags == null ? List.of() : List.of(tags.split(",")), voidReason,
                comments.stream().map((c) -> new Comment(c.by(), c.date().toString(), c.text())).toList(), batch,
                lines.stream().map((l) -> new Line(l.label(), l.qty(), l.unit().setScale(2).toPlainString())).toList(),
                claim.added(), claim.waived(), proofKinds, claim.held());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, ClaimLogRepository logs, ClaimLockRepository locks,
            ClaimRepository repository, ClaimCommentRepository comments, ClaimLineRepository lines,
            SettleBatchRepository batches, ObjectResponse<ClaimResponse> response) {
        response.send(ClaimResponse.from(claim, logs.find(claim.sheetId(), claim.id()),
                locks.lockedBy(claim.sheetId(), claim.id()),
                repository.lateEntry(claim.sheetId(), claim.id()),
                repository.reminded(claim.sheetId(), claim.id()),
                repository.ref(claim.sheetId(), claim.id()),
                repository.tags(claim.sheetId(), claim.id()),
                repository.voidReason(claim.sheetId(), claim.id()),
                comments.find(claim.sheetId(), claim.id()),
                batches.batch(claim.sheetId(), claim.id()),
                lines.find(claim.sheetId(), claim.id()),
                repository.photoProofs(claim.sheetId(), claim.id())));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaims {
    public void respond(@Val Sheet sheet, @Val List<Claim> claims, ClaimLogRepository logs, ClaimLockRepository locks,
            ClaimRepository repository, ClaimCommentRepository comments, ClaimLineRepository lines, SettleBatchRepository batches,
            ObjectResponse<List<ClaimResponse>> response) {
        Map<Long, List<ClaimLogLine>> log = logs.findAll(sheet.id());
        Map<Long, String> locked = locks.findAll(sheet.id());
        Set<Long> late = repository.lateEntries(sheet.id());
        Map<Long, LocalDate> reminded = repository.remindedAll(sheet.id());
        Map<Long, String> refs = repository.refs(sheet.id());
        Map<Long, String> tags = repository.tagsAll(sheet.id());
        Map<Long, String> voidReasons = repository.voidReasons(sheet.id());
        Map<Long, Integer> batched = batches.batches(sheet.id());
        Map<Long, List<ClaimComment>> commented = comments.findAll(sheet.id());
        Map<Long, List<ClaimLine>> lined = lines.findAll(sheet.id());
        Map<Long, Integer> photos = repository.photoProofsAll(sheet.id());
        response.send(claims.stream()
                .map((c) -> ClaimResponse.from(c, log.getOrDefault(c.id(), List.of()), locked.get(c.id()),
                        late.contains(c.id()), reminded.get(c.id()), refs.get(c.id()),
                        tags.get(c.id()), voidReasons.get(c.id()),
                        commented.getOrDefault(c.id(), List.of()), batched.get(c.id()),
                        lined.getOrDefault(c.id(), List.of()), photos.getOrDefault(c.id(), 0))).toList());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The claims' lines, each in the order added. */
@Repository
public class ClaimLineRepository {

    private final JdbcTemplate jdbc;

    public ClaimLineRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void append(String sheetId, ClaimLine line) {
        jdbc.update("INSERT INTO claim_line (sheet_id, claim_id, label, qty, unit) VALUES (?, ?, ?, ?, ?)",
                sheetId, line.claimId(), line.label(), line.qty(), line.unit());
    }

    /** The sheet's lines by claim id, each in the order added. */
    public Map<Long, List<ClaimLine>> findAll(String sheetId) {
        Map<Long, List<ClaimLine>> lines = new LinkedHashMap<>();
        jdbc.query("SELECT claim_id, label, qty, unit FROM claim_line WHERE sheet_id = ? ORDER BY id", (rs) -> {
            ClaimLine line = new ClaimLine(rs.getLong("claim_id"), rs.getString("label"), rs.getInt("qty"),
                    rs.getBigDecimal("unit").setScale(2));
            lines.computeIfAbsent(line.claimId(), (k) -> new ArrayList<>()).add(line);
        }, sheetId);
        return lines;
    }

    /** The claim's lines, in the order added. */
    public List<ClaimLine> find(String sheetId, long claimId) {
        List<ClaimLine> lines = new ArrayList<>();
        jdbc.query("SELECT claim_id, label, qty, unit FROM claim_line WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
                (rs) -> {
                    lines.add(new ClaimLine(rs.getLong("claim_id"), rs.getString("label"), rs.getInt("qty"),
                            rs.getBigDecimal("unit").setScale(2)));
                }, sheetId, claimId);
        return lines;
    }

    /** The lines' quantities times their unit amounts, added up. */
    public static BigDecimal total(List<ClaimLine> lines) {
        return lines.stream().map(ClaimLine::total).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }
}

    /**
     * A claim moved to another sheet by a transfer: its id there, the number it had on its old sheet (null: none)
     * and the old sheet's today when it was opened (its date when that is not known).
     */
    public record Moved(long id, String number, LocalDate opened) {
    }

    /**
     * Copy the person's claims to the other sheet's person, in the order they were added, keeping their status,
     * dates, notes, frozen figures, any figure a statement bound, tags, logs and comments, losing their references
     * and their batch; each claim's tags join the other sheet's tag list. The claims leave this sheet (with any lock
     * on them). Numbers are left as they were, to be given anew ({@link #renumberTransferred}).
     */
    public List<Moved> transfer(String sheetId, long personId, String to, long toPersonId) {
        List<Long> ids = jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                Long.class, sheetId, personId);
        List<Moved> moved = new java.util.ArrayList<>();
        for (long old : ids) {
            Map<String, Object> was = jdbc.queryForMap("SELECT c.claim_number, c.claim_date, (SELECT MIN(l.log_date)"
                    + " FROM claim_log l WHERE l.claim_id = c.id AND l.status = 'OPEN') AS opened FROM claim c"
                    + " WHERE c.id = ?", old);
            Map<String, Object> changed = new HashMap<>();
            changed.put("sheet_id", to);
            changed.put("person_id", toPersonId);
            changed.put("external_ref", null);
            changed.put("external_ref_key", null);
            changed.put("batch", null);
            long id = RowCopy.copy(jdbc, "claim", old, changed);
            jdbc.update("UPDATE claim_log SET sheet_id = ?, claim_id = ? WHERE claim_id = ?", to, id, old);
            jdbc.update("UPDATE claim_comment SET sheet_id = ?, claim_id = ? WHERE claim_id = ?", to, id, old);
            jdbc.update("UPDATE claim_line SET sheet_id = ?, claim_id = ? WHERE claim_id = ?", to, id, old);
            jdbc.update("DELETE FROM claim_lock WHERE sheet_id = ? AND claim_id = ?", sheetId, old);
            jdbc.update("DELETE FROM claim WHERE id = ?", old);
            String tags = tags(to, id);
            if (tags != null) {
                for (String tag : tags.split(",")) {
                    jdbc.update("MERGE INTO claim_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", to, tag);
                }
            }
            Object opened = was.get("opened") != null ? was.get("opened") : was.get("claim_date");
            moved.add(new Moved(id, (String) was.get("claim_number"),
                    opened instanceof Date d ? d.toLocalDate() : (LocalDate) opened));
        }
        return moved;
    }

    /**
     * Give the claims moved to the sheet their new numbers ({@code numbers}: old number to new); a correction or a
