package net.officefloor.hq.app.claim;

/** What a re-date submits: the claim's new date (yyyy-MM-dd; null or blank: none typed). */
public record RedateRequest(String date) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the re-date's body once, publishing its new date; refuses (400) a missing or malformed date. */
public class ValidateRedateRequest {
    public void validate(@RequestBody RedateRequest request, Out<NewClaimDate> date) throws InvalidClaimException {
        String typed = request == null || request.date() == null ? "" : request.date().trim();
        if (typed.isEmpty()) {
            throw new InvalidClaimException("Type the claim's new date.");
        }
        try {
            date.set(new NewClaimDate(LocalDate.parse(typed)));
        } catch (DateTimeParseException ex) {
            throw new InvalidClaimException("Type a date as yyyy-mm-dd.");
        }
    }
}
package net.officefloor.hq.app.claim;

/**
 * What a reassign submits: the id of the person the claim moves to (null: none chosen), and whether it is one of a
 * bulk move (a bulk move counts a claim already that person's as moved, rather than refusing it).
 */
public record ReassignRequest(Long personId, Boolean bulk) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the reassign's body once for later steps; refuses (400) one that names no person. */
public class ValidateReassignRequest {
    public void validate(@RequestBody ReassignRequest request, Out<ReassignRequest> body) throws InvalidClaimException {
        if (request == null || request.personId() == null) {
            throw new InvalidClaimException("Choose the person to move the claim to.");
        }
        body.set(request);
    }
}
# Move a claim to another person on the sheet (the body's personId). Only a steward moves a claim, and only a DRAFT,
# OPEN or PENDING one; a SETTLED or VOID claim, the claim's own person, an unknown person or one retired before the
# claim's date is refused (400) and writes nothing. A claim dated inside a closed period is refused (400).
# The claim keeps its date (a numbered claim takes the next number in its sequence; a draft gets none), loses any figure a statement bound it to (live again), and is listed as its
# new person's newest claim.
# A bulk move (body bulk=true) takes a claim already that person's as moved instead of refusing it.
