import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import type { Claim } from './claims';
import { AMOUNT, claimsKey } from './claims';
import { useOneAtATime } from '../../query/useOneAtATime';
import { useClaimError } from './claimError';

/** A quantity a line takes: a whole number, at least 1. */
const QTY = /^\d+$/;

// The claim's lines, in the order added, and the entries to add one: a label, a quantity and a unit amount. A claim
// with lines takes their quantities times their unit amounts, added up, as its amount. The server refuses a line on a
// claim that is not a DRAFT, in a closed period or locked by another user; the refusal shows as the claim's error.
export function ClaimLines({ claim }: { claim: Claim }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setError] = useClaimError(claim.id);
  const [label, setLabel] = useState('');
  const [qty, setQty] = useState('');
  const [unit, setUnit] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const add = useMutation({
    mutationFn: (body: { label: string; qty: string; unit: string }) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/lines?user=${encodeURIComponent(user)}`, body),
    onSuccess: async () => {
      setLabel('');
      setQty('');
      setUnit('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError('This line cannot be added (only a DRAFT claim, outside a closed period and not being edited by another user, takes lines).'),
  });

  return (
    <>
      <ol>
        {(claim.lines ?? []).map((l, i) => (
          <li key={i} data-testid="claim-lines-line">
            {`${l.label} ${l.qty} x ${l.unit}`}
          </li>
        ))}
      </ol>
      <input
        data-testid="claim-line-label"
        placeholder="Label"
        value={label}
        onChange={(e) => {
          setError('');
          setLabel(e.target.value);
        }}
      />{' '}
      <input
        data-testid="claim-line-qty"
        placeholder="Qty"
        size={4}
        value={qty}
        onChange={(e) => {
          setError('');
          setQty(e.target.value);
        }}
      />{' '}
      <input
        data-testid="claim-line-unit"
        placeholder="Unit"
        size={8}
        value={unit}
        onChange={(e) => {
          setError('');
          setUnit(e.target.value);
        }}
      />{' '}
      <button
        type="button"
        data-testid="claim-line-add"
        disabled={add.isPending}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` tells a refusal (400) from a conflict with someone else's save (409). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/**
 * The date this screen shows the sheet as of (yyyy-MM-dd), or '' when it shows the sheet now. It is
 * the `asof` search param (features/session/AsOf), read here so every read of the sheet carries it
 * and every change is refused while it is set.
 */
export function currentAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  return raw.replace(/^"(.*)"$/, '$1');
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // A screen showing the sheet as of a date changes nothing; loading a sheet is not a change.
  if (init?.method && init.method !== 'GET' && path !== '/api/sheets' && currentAsOf()) {
    throw new HttpError(`${init.method} ${path} refused: the sheet is shown as of ${currentAsOf()}`, 400);
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  const asOf = currentAsOf();
  if (asOf && path.startsWith('/api/sheets/')) {
    return send<T>(`${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`);
  }
  return send<T>(path);
}

/** Read the store as it holds it now, even while the screen shows the sheet as of a date. */

